/* Œconomia — dictionnaire des concepts
   Chaque entrée : id, nom, cat, court (définition), texte (développement), exemple, auteurs, questions, voir (concepts liés). */
OEC.conceptCats = {
  valeur: "Valeur, prix et marchés",
  macro: "Croissance, emploi et cycles",
  monnaie: "Monnaie et finance",
  echange: "Commerce et développement",
  repartition: "Répartition et bien-être",
  institutions: "Institutions et comportements"
};

OEC.concepts = [
  /* ---------- Valeur, prix et marchés ---------- */
  { id: "valeur-usage", nom: "Valeur d’usage et valeur d’échange", cat: "valeur",
    court: "L’utilité concrète d’un bien pour celui qui l’emploie, distincte de ce qu’il permet d’obtenir en échange.",
    texte: "La distinction remonte à Aristote, qui observe qu’une chaussure peut être portée ou échangée. Smith la formule par le paradoxe de l’eau et du diamant : la valeur d’usage de l’eau est immense, sa valeur d’échange presque nulle, et l’inverse pour le diamant. Les classiques en concluent que l’utilité est une condition de la valeur d’échange, mais non sa mesure, qu’ils cherchent dans le travail. Marx fait de la tension entre les deux le point de départ du Capital : sous le capitalisme, on produit des valeurs d’usage seulement en tant que supports de valeur d’échange. Les marginalistes dissolvent le paradoxe en montrant que c’est l’utilité de la dernière unité, non l’utilité totale, qui règle le prix.",
    exemple: "Un litre d’eau dans le désert et un litre d’eau au bord d’un lac ont la même valeur d’usage physiologique, mais pas la même valeur d’échange.",
    auteurs: ["aristote", "smith", "marx"], questions: ["valeur"], voir: ["valeur-travail", "utilite-marginale"] },

  { id: "valeur-travail", nom: "Valeur-travail", cat: "valeur",
    court: "Théorie selon laquelle la valeur d’échange d’un bien dépend de la quantité de travail nécessaire pour le produire.",
    texte: "Esquissée par Locke et Petty, la théorie prend chez Smith deux formes concurrentes : le travail incorporé dans un bien et le travail que ce bien permet d’acheter. Ricardo retient la première et l’étend au travail passé incorporé dans les outils, tout en reconnaissant qu’elle ne vaut qu’approximativement quand les capitaux ont des durées différentes. Marx l’affine en parlant de « travail socialement nécessaire », c’est-à-dire réalisé dans des conditions de productivité moyennes, et en tire la théorie de la plus-value. La révolution marginaliste l’a abandonnée au profit de l’utilité et de la rareté. Le « problème de la transformation » des valeurs en prix, soulevé par Böhm-Bawerk en 1896, reste débattu chez les économistes marxistes et sraffaiens.",
    exemple: "Pour Ricardo, si un castor demande deux fois plus de travail à chasser qu’un daim, il s’échangera contre deux daims, exemple que Smith avait déjà utilisé.",
    auteurs: ["smith", "ricardo", "marx"], questions: ["valeur"], voir: ["plus-value", "utilite-marginale", "prix-naturel"] },

  { id: "utilite-marginale", nom: "Utilité marginale", cat: "valeur",
    court: "La satisfaction apportée par la dernière unité consommée d’un bien ; elle diminue généralement avec la quantité.",
    texte: "Le premier verre d’eau étanche une soif intense, le dixième ne sert plus qu’à arroser une plante. Formulée dès 1854 par Hermann Gossen, l’idée est redécouverte simultanément en 1871-1874 par Jevons, Menger et Walras. Elle explique la demande : un consommateur répartit son budget de sorte que le dernier franc dépensé lui apporte la même satisfaction dans tous les usages. Elle résout le paradoxe de l’eau et du diamant : l’eau abondante a une utilité marginale faible, le diamant rare une utilité marginale élevée. Le raisonnement « à la marge » s’est ensuite étendu à toute l’économie : coût marginal, productivité marginale du travail, propension marginale à consommer. Pareto a montré qu’il n’est pas nécessaire de mesurer l’utilité : un classement des préférences suffit.",
    exemple: "Un restaurateur décide d’ouvrir le dimanche si la recette de ce jour supplémentaire dépasse son coût supplémentaire, quel que soit le profit moyen de la semaine.",
    auteurs: ["walras", "marshall", "pareto"], questions: ["valeur"], voir: ["valeur-usage", "offre-demande", "optimum-pareto"] },

  { id: "prix-naturel", nom: "Prix naturel et prix de marché", cat: "valeur",
    court: "Chez les classiques, le prix de marché fluctue autour d’un prix naturel qui couvre salaires, profits et rentes aux taux ordinaires.",
    texte: "Smith distingue le prix qui s’observe un jour donné, soumis aux aléas de l’offre et de la demande, et le prix naturel, « centre de gravité » vers lequel la concurrence le ramène. Si le prix de marché dépasse le prix naturel, les profits élevés attirent des capitaux dans la branche, l’offre augmente et le prix baisse ; dans le cas inverse, les capitaux se retirent. Ricardo et Marx reprennent ce mécanisme de gravitation, le second sous le nom de prix de production. Marshall le réinterprète en distinguant prix de courte période, dominés par la demande, et prix de longue période, réglés par le coût de production. Le mécanisme suppose la mobilité des capitaux et l’absence de monopole.",
    exemple: "Après une mauvaise récolte de café, le prix grimpe ; quelques années plus tard, de nouvelles plantations le ramènent vers le coût de production.",
    auteurs: ["smith", "ricardo", "marx", "marshall"], questions: ["valeur"], voir: ["offre-demande", "valeur-travail"] },

  { id: "offre-demande", nom: "Offre et demande", cat: "valeur",
    court: "Le prix et la quantité échangés résultent de la rencontre d’une courbe de demande décroissante et d’une courbe d’offre croissante.",
    texte: "Cournot dessine la première courbe de demande en 1838 ; Marshall en fait en 1890 l’outil de base de l’économie. La demande baisse quand le prix monte, parce que les acheteurs se tournent vers des substituts et que leur pouvoir d’achat diminue. L’offre augmente avec le prix, qui rend rentable une production plus coûteuse. L’élasticité mesure la sensibilité de la quantité au prix : la demande de pain ou d’essence est peu élastique à court terme, celle d’une marque particulière très élastique. Ces outils servent à prévoir l’effet d’une taxe, d’un prix plafond ou d’un choc d’offre. Ils supposent un marché concurrentiel et raisonnent « toutes choses égales par ailleurs », ce qui en fixe les limites.",
    exemple: "Une taxe sur le tabac est en grande partie payée par les fumeurs, parce que leur demande est peu élastique.",
    auteurs: ["marshall", "walras"], questions: ["valeur"], voir: ["elasticite", "surplus", "equilibre-general", "utilite-marginale"], lab: 0 },

  { id: "elasticite", nom: "Élasticité", cat: "valeur",
    court: "La sensibilité de la quantité demandée ou offerte à une variation du prix ou du revenu, mesurée en pour cent.",
    texte: "Marshall nomme l’élasticité en 1890 : de combien, en pour cent, la quantité demandée varie-t-elle quand le prix varie de 1 % ? Une demande est inélastique quand les acheteurs réagissent peu (essence à court terme, tabac, médicaments), élastique quand ils ont des substituts proches (une marque parmi d’autres). Le chiffre indique si une hausse de prix augmente ou diminue la recette du vendeur, et quel côté du marché supporte une taxe. La même mesure s’applique au revenu, avec la loi d’Engel sur la part de l’alimentation, et au prix d’un autre bien, pour distinguer substituts et compléments.",
    exemple: "L’impôt sur le tabac rapporte environ deux milliards de francs par an à l’AVS et à l’AI, parce que la demande de cigarettes réagit peu au prix.",
    auteurs: ["marshall", "veblen"], questions: ["valeur", "etat"], voir: ["offre-demande", "surplus", "consommation-ostentatoire", "externalite"], lab: 0 },

  { id: "surplus", nom: "Surplus du consommateur et perte sèche", cat: "valeur",
    court: "L’écart entre ce qu’un acheteur aurait accepté de payer et ce qu’il paie ; la perte sèche est le surplus détruit par une distorsion.",
    texte: "Jules Dupuit, ingénieur des Ponts et Chaussées, en a l’intuition en 1844 en se demandant ce que vaut un pont pour ses usagers ; Marshall en fait un concept général. Le surplus du consommateur est l’aire située sous la courbe de demande et au-dessus du prix. Le surplus du producteur est l’écart entre le prix et le coût. Une taxe, un quota ou un monopole réduisent la quantité échangée : certains échanges qui auraient profité aux deux parties n’ont plus lieu. La perte sèche mesure cette valeur détruite, qui n’est récupérée par personne, ni par l’État ni par les entreprises. C’est l’un des principaux outils de l’analyse coûts-avantages des politiques publiques.",
    exemple: "Un péage trop élevé sur un pont vide fait perdre l’usage du pont à des voyageurs qui l’auraient emprunté à un prix plus bas, sans rapporter davantage.",
    auteurs: ["marshall"], questions: ["etat"], voir: ["elasticite", "offre-demande", "optimum-pareto"], lab: 0 },

  { id: "equilibre-general", nom: "Équilibre général", cat: "valeur",
    court: "Situation où l’offre égale la demande simultanément sur tous les marchés, les prix étant interdépendants.",
    texte: "Walras formule en 1874 l’idée que les marchés ne peuvent être étudiés isolément : le salaire influe sur la demande de tous les biens, le prix du pétrole sur celui de tous les transports. Il écrit l’économie comme un système d’équations simultanées. Arrow et Debreu démontrent en 1954 qu’un tel équilibre existe sous certaines conditions (préférences convexes, absence de rendements croissants, marchés complets). Les deux théorèmes du bien-être établissent qu’il est efficace au sens de Pareto. Mais les travaux de Sonnenschein, Mantel et Debreu montrent dans les années 1970 qu’il n’est en général ni unique ni stable. L’équilibre général reste le cadre de référence de la microéconomie théorique et des modèles appliqués de politique commerciale ou fiscale.",
    exemple: "Une taxe carbone change le prix de l’énergie, donc celui de l’acier, des transports, de l’alimentation et finalement les salaires réels : seul un modèle d’équilibre général suit ces effets en chaîne.",
    auteurs: ["walras", "pareto", "samuelson"], questions: ["valeur"], voir: ["optimum-pareto", "offre-demande"] },

  { id: "cout-opportunite", nom: "Coût d’opportunité", cat: "valeur",
    court: "La valeur de la meilleure option à laquelle on renonce en faisant un choix.",
    texte: "Développé par l’Autrichien Friedrich von Wieser à la fin du XIXe siècle, le concept rappelle que le vrai coût d’une décision n’est pas seulement ce qu’on paie, mais ce qu’on sacrifie. Le coût d’une année d’études inclut le salaire qu’on aurait gagné en travaillant. Le coût d’un hôpital public est l’école qu’on n’a pas construite. C’est sur ce concept que repose l’avantage comparatif de Ricardo : un pays doit se spécialiser dans la production dont le coût d’opportunité, mesuré en autres biens sacrifiés, est le plus faible. Le coût d’opportunité est aussi au cœur de la théorie de l’intérêt : prêter son argent, c’est renoncer à l’utiliser.",
    exemple: "Une avocate qui tape plus vite que sa secrétaire a pourtant intérêt à lui laisser la frappe : chaque heure de frappe lui coûterait une heure de conseil facturée bien plus cher.",
    auteurs: ["ricardo", "mises"], questions: ["commerce"], voir: ["avantage-comparatif"] },

  { id: "concurrence-imparfaite", nom: "Monopole, oligopole et monopsone", cat: "valeur",
    court: "Marchés où un ou quelques acteurs peuvent influencer les prix, à la vente ou à l’achat.",
    texte: "Cournot analyse dès 1838 le monopole et le duopole. Le monopoleur restreint sa production pour vendre plus cher : il maximise son profit là où sa recette marginale égale son coût marginal, au détriment des consommateurs. Joan Robinson et Edward Chamberlin généralisent en 1933 l’analyse à la concurrence imparfaite, où chaque firme vend un produit un peu différencié. Robinson introduit le monopsone, un acheteur dominant, notamment sur le marché du travail. La théorie des jeux, à partir des années 1950, permet d’analyser les oligopoles, où chaque firme anticipe la réaction des autres. Ces travaux fondent le droit de la concurrence, et les débats actuels sur le pouvoir des grandes plateformes numériques.",
    exemple: "Dans une petite ville dominée par un seul grand employeur, celui-ci peut payer moins qu’ailleurs sans perdre ses salariés, faute d’alternative.",
    auteurs: ["robinson", "galbraith", "schumpeter"], questions: ["etat", "inegalites"], voir: ["offre-demande", "surplus"] },

  { id: "division-travail", nom: "Division du travail", cat: "valeur",
    court: "La spécialisation des tâches entre travailleurs, entreprises ou pays, source majeure de productivité.",
    texte: "Smith ouvre la Richesse des nations par la manufacture d’épingles : dix ouvriers spécialisés en produisent quarante-huit mille par jour, quand chacun seul n’en ferait pas vingt. Il donne trois raisons : l’habileté accrue par la répétition, le temps gagné à ne pas changer de tâche, et l’invention de machines par ceux qui se concentrent sur une opération. La division du travail est limitée par l’étendue du marché : un village ne fait pas vivre un fabricant de clous. Smith en voit aussi le coût humain, l’abrutissement de l’ouvrier, que Marx développera. Durkheim en fera en 1893 le fondement de la solidarité dans les sociétés modernes, et les chaînes de valeur mondiales en sont aujourd’hui l’extension planétaire.",
    exemple: "Un smartphone mobilise des composants conçus aux États-Unis, fabriqués en Corée, à Taïwan et au Japon, et assemblés en Chine ou en Inde.",
    auteurs: ["smith", "marx", "khaldoun"], questions: ["valeur", "commerce"], voir: ["avantage-comparatif", "rendements-croissants"] },

  /* ---------- Croissance, emploi et cycles ---------- */
  { id: "demande-effective", nom: "Demande effective", cat: "macro",
    court: "Chez Keynes, le niveau de demande anticipé par les entreprises, qui détermine la production et l’emploi.",
    texte: "Adam Smith parle déjà en 1776 de « demande effective » pour désigner une demande accompagnée des moyens de payer ; Malthus s’en sert en 1820 pour soutenir qu’elle peut faire défaut. Keynes en fait en 1936 le pivot de sa théorie : les entrepreneurs embauchent en fonction des ventes qu’ils anticipent, et cette demande dépend de la consommation des ménages et de l’investissement des entreprises. Rien ne garantit qu’elle corresponde au plein emploi. Une économie peut ainsi se fixer dans un équilibre de sous-emploi, où les chômeurs voudraient travailler au salaire courant sans trouver d’embauche. Contre la loi de Say, Keynes soutient que la production ne crée pas automatiquement sa propre demande, car une partie des revenus est épargnée et l’investissement dépend d’anticipations fragiles.",
    exemple: "En 2009, les usines automobiles tournent à la moitié de leurs capacités : ce n’est pas faute de machines ou de travailleurs, mais faute d’acheteurs.",
    auteurs: ["keynes", "malthus"], questions: ["crises"], voir: ["loi-debouches", "multiplicateur", "paradoxe-epargne"] },

  { id: "loi-debouches", nom: "Loi des débouchés", cat: "macro",
    court: "Chez Say, l’idée que toute production crée les revenus nécessaires à son achat, rendant impossible une surproduction générale.",
    texte: "Un producteur ne vend que pour acheter : la monnaie qu’il reçoit lui brûle les doigts, et il la dépense en biens de consommation ou d’investissement. Les produits s’échangent donc, en dernière analyse, contre des produits. Un engorgement sur un marché suppose une pénurie sur un autre, et le déplacement des capitaux le corrige. Ricardo et James Mill adoptent cette loi, contestée par Malthus et Sismondi. Keynes la résume en « l’offre crée sa propre demande » et la rejette : si l’on garde de la monnaie par précaution, une partie des revenus n’est pas dépensée, et la demande globale peut manquer durablement. La loi reste valable dans un sens affaibli : à long terme, ce sont les capacités de production qui bornent la richesse.",
    exemple: "Pour Say, une bonne récolte de blé enrichit aussi les fabricants de chaussures, car les paysans auront de quoi en acheter.",
    auteurs: ["say", "ricardo", "malthus", "keynes"], questions: ["crises"], voir: ["demande-effective", "preference-liquidite"] },

  { id: "multiplicateur", nom: "Multiplicateur", cat: "macro",
    court: "Rapport entre la hausse finale du revenu national et la dépense initiale qui l’a provoquée.",
    texte: "Formalisé par Richard Kahn en 1931 pour l’emploi, repris par Keynes pour le revenu, le multiplicateur repose sur un enchaînement simple. Une dépense publique de 100 devient le revenu d’entreprises et de salariés, qui en dépensent une part c, laquelle devient le revenu d’autres agents, et ainsi de suite. L’effet total est 100 / (1 − c). Il est réduit par l’épargne, les impôts et les importations, qui sont autant de « fuites ». Les débats empiriques sur sa valeur sont vifs : il est plus élevé en récession profonde, quand les taux sont à zéro, qu’en temps normal. En 2013, Olivier Blanchard et Daniel Leigh montrent que les prévisions de 2010 supposaient un multiplicateur d’environ 0,5, alors qu’il se situait plutôt entre 0,9 et 1,7. Les critiques invoquent l’éviction de l’investissement privé et l’équivalence ricardienne.",
    exemple: "En sous-estimant le multiplicateur, les plans d’austérité européens de 2010-2012 ont sous-estimé la récession qu’ils allaient provoquer, notamment en Grèce.",
    auteurs: ["keynes", "samuelson"], questions: ["crises", "etat"], voir: ["demande-effective", "equivalence-ricardienne"], lab: 1 },

  { id: "paradoxe-epargne", nom: "Paradoxe de l’épargne", cat: "macro",
    court: "Si tout le monde épargne davantage en même temps, le revenu baisse et l’épargne totale peut finir par diminuer.",
    texte: "Pour un ménage isolé, épargner davantage enrichit. Pour l’économie entière, le raisonnement change : la dépense de l’un est le revenu de l’autre. Si tous réduisent leur consommation en même temps, les ventes baissent, les entreprises produisent moins et licencient, les revenus diminuent, et l’épargne totale, qui dépend du revenu, peut finir plus basse qu’au départ. L’idée remonte à La Fable des abeilles de Mandeville (1714), que Keynes cite longuement. Elle n’a de force qu’en situation de sous-emploi : au plein emploi, l’épargne finance l’investissement et la croissance future. Elle illustre le sophisme de composition, selon lequel ce qui est vrai pour chacun n’est pas forcément vrai pour tous.",
    exemple: "En 2009-2010, les ménages et les États européens cherchent à se désendetter en même temps ; la demande s’effondre et le ratio de dette rapporté au PIB augmente.",
    auteurs: ["keynes", "malthus"], questions: ["crises"], voir: ["demande-effective", "multiplicateur"] },

  { id: "courbe-phillips", nom: "Courbe de Phillips", cat: "macro",
    court: "Relation inverse observée entre taux de chômage et taux d’inflation.",
    texte: "En 1958, A. W. Phillips trouve sur près d’un siècle de données britanniques une relation stable : quand le chômage est faible, les salaires montent vite. Samuelson et Solow la transposent aux prix en 1960 et y voient un menu offert aux gouvernants. Friedman et Phelps objectent en 1967-1968 que la relation dépend des anticipations : si l’inflation devient attendue, elle se déplace, et à long terme la courbe est verticale au niveau du chômage naturel. La stagflation des années 1970 leur donne raison. Depuis les années 1990, la courbe paraît très « plate » : l’inflation réagit peu au chômage, ce qui a surpris lors de la remontée des prix de 2021-2022, où elle s’est redressée.",
    exemple: "En 2019, le chômage américain tombe à 3,5 % sans que l’inflation dépasse 2 %, signe d’une courbe de Phillips aplatie.",
    auteurs: ["samuelson", "friedman", "lucas"], questions: ["monnaie", "crises"], voir: ["taux-naturel", "anticipations-rationnelles", "stagflation"] },

  { id: "taux-naturel", nom: "Taux de chômage naturel", cat: "macro",
    court: "Le taux de chômage compatible avec une inflation stable, déterminé par les structures du marché du travail.",
    texte: "Friedman introduit la notion en 1967 : même en l’absence de chocs, un certain chômage subsiste, dû aux changements d’emploi, à l’inadéquation des qualifications et aux institutions du marché du travail. Le maintenir artificiellement plus bas exige une inflation croissante. On parle aussi de NAIRU (taux de chômage n’accélérant pas l’inflation). Ce taux n’est pas « naturel » au sens d’immuable : il dépend des allocations chômage, du salaire minimum, de la formation, de la mobilité géographique. Blanchard et Summers ont montré en 1986 qu’il peut lui-même augmenter après une longue récession, par hystérèse. Les estimations sont imprécises, ce qui rend son usage délicat pour les banques centrales.",
    exemple: "Dans les années 1990, la Fed d’Alan Greenspan laisse le chômage descendre sous les estimations du NAIRU, pariant sur des gains de productivité ; l’inflation reste contenue.",
    auteurs: ["friedman", "summers"], questions: ["monnaie"], voir: ["courbe-phillips", "hysterese"] },

  { id: "stagflation", nom: "Stagflation", cat: "macro",
    court: "Combinaison d’une croissance faible, d’un chômage élevé et d’une forte inflation.",
    texte: "Le terme apparaît au Royaume-Uni en 1965. Il désigne une situation que la courbe de Phillips des années 1960 jugeait improbable : inflation et chômage montent ensemble. Les années 1970 en offrent l’exemple type, avec les chocs pétroliers de 1973 et 1979, l’indexation des salaires sur les prix et des anticipations d’inflation désancrées. Les remèdes keynésiens se heurtent à un dilemme : relancer aggrave l’inflation, freiner aggrave le chômage. La stagflation a provoqué le tournant monétariste et la priorité donnée à la stabilité des prix. Le risque a été évoqué à nouveau en 2022, après la flambée de l’énergie consécutive à l’invasion de l’Ukraine.",
    exemple: "En 1974-1975, les États-Unis connaissent à la fois une inflation supérieure à 10 % et un chômage qui atteint 9 %.",
    auteurs: ["friedman", "keynes"], questions: ["monnaie", "crises"], voir: ["courbe-phillips", "taux-naturel"] },

  { id: "anticipations-rationnelles", nom: "Anticipations rationnelles", cat: "macro",
    court: "Hypothèse selon laquelle les agents utilisent toute l’information disponible et ne se trompent pas systématiquement.",
    texte: "Proposée par John Muth en 1961, l’hypothèse est généralisée à la macroéconomie par Lucas, Sargent et Wallace dans les années 1970. Elle ne suppose pas que les agents connaissent l’avenir, mais que leurs erreurs sont imprévisibles et se compensent en moyenne. Elle a des conséquences fortes : une politique monétaire anticipée n’a pas d’effet réel durable, et les modèles qui supposent des agents naïfs se trompent dès que la politique change. L’hypothèse a imposé la cohérence entre la théorie et le comportement des agents. Elle est critiquée par l’économie comportementale et par ceux qui insistent, comme Keynes, sur l’incertitude radicale, où les probabilités elles-mêmes sont inconnues.",
    exemple: "Si une banque centrale annonce de façon crédible qu’elle ramènera l’inflation à 2 %, les salariés modèrent leurs revendications, ce qui facilite la désinflation.",
    auteurs: ["lucas", "friedman", "kahneman"], questions: ["monnaie"], voir: ["courbe-phillips", "aversion-pertes"] },

  { id: "hysterese", nom: "Hystérèse du chômage", cat: "macro",
    court: "Phénomène par lequel un chômage élevé et durable augmente le chômage d’équilibre lui-même.",
    texte: "Le terme vient de la physique, où il désigne un système qui garde la trace des chocs passés. Blanchard et Summers l’appliquent en 1986 à l’Europe, où le chômage, monté après les chocs pétroliers, ne redescend pas. Plusieurs mécanismes y contribuent : les chômeurs de longue durée perdent leurs compétences et leurs réseaux, les employeurs s’en méfient, les salariés en place négocient des salaires sans tenir compte des exclus. Une récession peut donc avoir des effets permanents sur l’emploi et la production. L’argument justifie des politiques de relance énergiques pour éviter que le chômage ne s’installe, et a pesé dans les réponses budgétaires massives à la pandémie de 2020.",
    exemple: "En Espagne, après 2008, une grande partie des chômeurs de longue durée n’a pas retrouvé d’emploi stable même lors de la reprise.",
    auteurs: ["summers"], questions: ["crises"], voir: ["taux-naturel", "stagnation-seculaire"] },

  { id: "stagnation-seculaire", nom: "Stagnation séculaire", cat: "macro",
    court: "Insuffisance chronique de la demande due à un excès d’épargne sur l’investissement, avec des taux d’intérêt durablement bas.",
    texte: "Alvin Hansen, disciple américain de Keynes, forge l’expression en 1938 : il craint que le ralentissement démographique et la fin de la conquête des terres n’étouffent l’investissement. La reprise d’après-guerre fait oublier l’idée. Larry Summers la relance en 2013 face à la lenteur de la reprise post-2008. Vieillissement, inégalités, faible besoin en capital des entreprises numériques et épargne des pays émergents auraient fait chuter le taux d’intérêt d’équilibre, peut-être sous zéro. La politique monétaire est alors impuissante, et l’économie oscille entre demande insuffisante et bulles. La remontée de l’inflation et des taux après 2021 a relancé le débat sur la persistance de ce phénomène.",
    exemple: "À plusieurs reprises entre 2015 et 2021, les taux d’intérêt à dix ans sont négatifs en Allemagne, en Suisse et au Japon.",
    auteurs: ["summers", "keynes", "krugman"], questions: ["crises"], voir: ["trappe-liquidite", "demande-effective"] },

  { id: "cycles", nom: "Cycles économiques", cat: "macro",
    court: "Alternance récurrente de phases d’expansion et de contraction de l’activité.",
    texte: "Clément Juglar établit en 1862 que les crises reviennent tous les sept à onze ans environ, liées au crédit et à l’investissement. Joseph Kitchin identifie en 1923 des cycles courts, d’environ quarante mois, liés aux stocks. Nikolaï Kondratiev propose en 1925 des ondes longues d’un demi-siècle, ce qui lui vaudra d’être fusillé sous Staline en 1938. Schumpeter rattache ces cycles à l’arrivée des innovations en grappes. Les théories divergent sur leur origine : chocs extérieurs ou dynamique interne, monnaie, investissement, finance. Les macroéconomistes contemporains préfèrent parler de fluctuations irrégulières, mais la question de leur cause, demande ou offre, reste au cœur des débats.",
    exemple: "Pour les tenants des cycles longs, la machine à vapeur, le chemin de fer, l’électricité, l’automobile et l’informatique ont chacun ouvert une onde d’expansion.",
    auteurs: ["schumpeter", "marx", "minsky", "hayek"], questions: ["crises"], voir: ["destruction-creatrice", "instabilite-financiere"] },

  { id: "destruction-creatrice", nom: "Destruction créatrice", cat: "macro",
    court: "Processus par lequel les innovations détruisent les activités anciennes en même temps qu’elles en créent de nouvelles.",
    texte: "L’expression, que Schumpeter popularise en 1942, désigne le mouvement par lequel le capitalisme se transforme de l’intérieur. Le chemin de fer ruine les diligences, la photographie numérique Kodak, le streaming les vidéoclubs. Pour Schumpeter, la concurrence décisive n’est pas celle des prix entre producteurs identiques, mais celle du produit nouveau, qui menace l’existence même des entreprises en place. Les théories de la croissance schumpétériennes, développées par Philippe Aghion et Peter Howitt, en ont fait un modèle formel : la croissance passe par le remplacement des entreprises les moins productives. Acemoglu et Robinson montrent que les élites cherchent souvent à bloquer ce processus qui menace leurs positions.",
    exemple: "Entre 1990 et 2010, la demande de pellicule photographique s’effondre et Kodak finit en faillite en 2012, tandis que naissent celles des appareils numériques et des réseaux sociaux de partage d’images.",
    auteurs: ["schumpeter", "acemoglu", "marx", "mazzucato"], questions: ["crises", "inegalites"], voir: ["modele-solow", "cycles", "institutions-inclusives"] },

  { id: "pib", nom: "PIB et ses limites", cat: "macro",
    court: "Le produit intérieur brut mesure la valeur ajoutée produite sur un territoire en une année.",
    texte: "La comptabilité nationale naît dans les années 1930, avec Simon Kuznets aux États-Unis et Richard Stone au Royaume-Uni, pour mesurer l’effondrement de la Dépression puis organiser l’effort de guerre. Le PIB additionne les valeurs ajoutées, ce qui revient à additionner les revenus ou les dépenses finales. Kuznets lui-même avertit en 1934 qu’on ne peut guère en déduire le bien-être d’une nation. Le PIB ignore le travail domestique, les loisirs, l’épuisement des ressources, la répartition des revenus et les dégâts environnementaux, qui peuvent même l’augmenter quand il faut les réparer. Le rapport Stiglitz-Sen-Fitoussi (2009) a proposé de le compléter par des indicateurs de bien-être, de soutenabilité et d’inégalités.",
    exemple: "Une marée noire augmente le PIB par les travaux de nettoyage qu’elle provoque.",
    auteurs: ["sen", "quesnay", "waring"], questions: ["croissance"], voir: ["modele-solow", "capabilites"] },

  { id: "modele-solow", nom: "Croissance et modèle de Solow", cat: "macro",
    court: "Un modèle qui explique la croissance de long terme par l’accumulation du capital, la population et le progrès technique.",
    texte: "Robert Solow propose en 1956 le modèle de référence de la croissance. Le capital a des rendements décroissants : chaque machine supplémentaire rapporte moins que la précédente. Un pays qui ne fait qu’épargner et investir atteint donc un état stationnaire où le revenu par habitant cesse de croître ; épargner davantage élève son niveau de vie, pas son rythme de croissance. Seul le progrès technique permet une croissance durable. En 1957, Solow calcule qu’il explique sept huitièmes de la hausse de la production par heure aux États-Unis de 1909 à 1949. Le modèle prédit aussi que les pays pauvres rattrapent les riches, ce qui ne s’observe qu’entre pays aux conditions comparables. Les théories de la croissance endogène et des institutions sont nées de ses limites.",
    exemple: "Depuis le début des années 2000, une part importante de la croissance du PIB suisse vient de la hausse de la population ; le PIB par habitant, qui dépend de la productivité, progresse plus lentement.",
    auteurs: ["samuelson", "lucas", "krugman", "acemoglu"], questions: ["croissance", "inegalites"], voir: ["destruction-creatrice", "institutions-inclusives", "pib", "stagnation-seculaire"] },

  /* ---------- Monnaie et finance ---------- */
  { id: "fonctions-monnaie", nom: "Fonctions de la monnaie", cat: "monnaie",
    court: "La monnaie sert d’unité de compte, d’intermédiaire des échanges et de réserve de valeur.",
    texte: "Aristote voit déjà la monnaie comme une mesure commune qui rend les biens commensurables. Les économistes lui reconnaissent trois fonctions. Unité de compte, elle permet d’exprimer tous les prix dans un même étalon. Intermédiaire des échanges, elle évite la « double coïncidence des besoins » du troc. Réserve de valeur, elle permet de différer une dépense. Les classiques insistent sur la deuxième fonction ; Keynes sur la troisième, qui permet de garder sa richesse sous forme liquide et donc de ne pas dépenser. Aujourd’hui, la monnaie est créée principalement par les banques commerciales lorsqu’elles accordent des crédits, sous le contrôle de la banque centrale. Les cryptomonnaies remplissent mal la fonction d’unité de compte, en raison de leur volatilité.",
    exemple: "Dans l’Allemagne de 1923, le mark perd sa fonction de réserve de valeur : les salaires sont versés deux fois par jour et dépensés aussitôt.",
    auteurs: ["aristote", "keynes", "hayek"], questions: ["monnaie"], voir: ["theorie-quantitative", "preference-liquidite"] },

  { id: "theorie-quantitative", nom: "Théorie quantitative de la monnaie", cat: "monnaie",
    court: "Théorie selon laquelle le niveau général des prix varie proportionnellement à la quantité de monnaie.",
    texte: "Jean Bodin attribue en 1568 la hausse des prix européens à l’afflux d’argent américain. Hume en tire en 1752 le mécanisme des flux de métal. Irving Fisher l’écrit en 1911 sous forme d’équation : M × V = P × Q, où M est la masse monétaire, V la vitesse de circulation, P le niveau des prix et Q la production réelle. C’est une identité comptable ; elle devient une théorie si l’on suppose V et Q indépendants de M. Friedman la réhabilite dans les années 1950 et 1960. Elle explique bien les hyperinflations et les tendances de long terme. Elle fonctionne mal à court terme et en période de crise, où la vitesse de circulation chute brutalement, comme après 2008.",
    exemple: "Entre 2008 et 2014, la base monétaire américaine est multipliée par plus de quatre sans provoquer d’inflation, car les banques conservent ces liquidités.",
    auteurs: ["friedman", "ricardo", "keynes"], questions: ["monnaie"], voir: ["politique-monetaire", "fonctions-monnaie", "trappe-liquidite"], lab: 5 },

  { id: "politique-monetaire", nom: "Politique monétaire", cat: "monnaie",
    court: "L’action de la banque centrale sur le coût de l’argent, d’abord pour garder des prix stables.",
    texte: "La banque centrale fixe un taux directeur, qui se répercute sur les taux des crédits, des hypothèques et de l’épargne. Quand l’inflation monte, elle le relève : le crédit devient plus cher, la demande ralentit, la monnaie s’apprécie, et la hausse des prix se calme, avec un délai d’un à deux ans. Quand l’économie faiblit, elle le baisse. La crédibilité compte autant que le taux : si chacun croit à des prix stables, salaires et prix s’ajustent en conséquence. Depuis 2008, les banques centrales recourent aussi à des instruments exceptionnels : taux négatifs, achats massifs de titres et, en Suisse, interventions sur le marché des changes. Leur indépendance et l’étendue de leur mandat restent débattues.",
    exemple: "Face à une inflation de 3,5 % en août 2022, la BNS a relevé son taux directeur de −0,25 % à 1,75 % en un an.",
    auteurs: ["friedman", "keynes", "lucas", "kelton"], questions: ["monnaie", "crises"], voir: ["taux-de-change", "theorie-quantitative", "monnaie-endogene", "trappe-liquidite", "anticipations-rationnelles", "preteur-dernier-ressort", "courbe-phillips"] },

  { id: "preference-liquidite", nom: "Préférence pour la liquidité", cat: "monnaie",
    court: "Chez Keynes, le désir de détenir de la monnaie plutôt que des titres, qui détermine le taux d’intérêt.",
    texte: "Pourquoi garder de la monnaie qui ne rapporte rien plutôt que des obligations qui rapportent un intérêt ? Keynes distingue trois motifs : la transaction, pour régler les dépenses courantes ; la précaution, face aux imprévus ; la spéculation, quand on anticipe une baisse du prix des titres. Le taux d’intérêt est alors le prix de la renonciation à la liquidité, et non la récompense de l’épargne comme chez les classiques. En période d’incertitude, la préférence pour la liquidité augmente : chacun veut de la monnaie, le taux d’intérêt reste élevé ou la monnaie supplémentaire est thésaurisée, et l’investissement ne repart pas. C’est l’une des principales ruptures de la Théorie générale avec la tradition classique.",
    exemple: "En mars 2020, au début de la pandémie, même les bons du Trésor américain sont vendus : les investisseurs veulent de la liquidité pure, et la Fed doit intervenir massivement.",
    auteurs: ["keynes", "minsky"], questions: ["monnaie", "crises"], voir: ["trappe-liquidite", "fonctions-monnaie", "loi-debouches"] },

  { id: "trappe-liquidite", nom: "Trappe à liquidité", cat: "monnaie",
    court: "Situation où les taux d’intérêt sont si bas que la création monétaire ne stimule plus la dépense.",
    texte: "Évoquée par Keynes, nommée par Dennis Robertson, la trappe à liquidité est longtemps restée une curiosité théorique. Le Japon des années 1990 lui redonne réalité : les taux tombent à zéro, la banque centrale crée de la monnaie, mais les prix stagnent et la croissance ne repart pas. Krugman l’analyse en 1998 et propose que la banque centrale s’engage de façon crédible à laisser l’inflation monter, pour rendre les taux réels négatifs. Après 2008, les grandes banques centrales s’y trouvent à leur tour et recourent à des instruments non conventionnels : achats massifs de titres (assouplissement quantitatif), engagements sur les taux futurs, taux négatifs. La relance budgétaire redevient alors l’outil principal.",
    exemple: "Entre 2015 et 2022, la Banque nationale suisse applique un taux directeur de −0,75 %, l’un des plus bas du monde.",
    auteurs: ["keynes", "krugman", "summers"], questions: ["monnaie", "crises"], voir: ["politique-monetaire", "preference-liquidite", "stagnation-seculaire"] },

  { id: "instabilite-financiere", nom: "Hypothèse d’instabilité financière", cat: "monnaie",
    court: "Chez Minsky, l’idée que les périodes de stabilité poussent à un endettement croissant qui rend le système fragile.",
    texte: "Minsky part d’un constat : une économie capitaliste moderne est un réseau d’engagements financiers, où chacun doit honorer ses dettes avec des revenus futurs incertains. Après une crise, prêteurs et emprunteurs sont prudents. À mesure que les années passent sans incident, la confiance grandit, les marges de sécurité s’amenuisent et l’on passe du financement couvert au financement spéculatif, puis au financement Ponzi. Le système devient vulnérable au moindre choc, une hausse des taux ou une baisse des prix des actifs, qui déclenche des ventes forcées en cascade. La stabilité est donc déstabilisante. La crise de 2008 a fait de cette hypothèse une référence pour les régulateurs.",
    exemple: "Entre 2001 et 2006, les crédits immobiliers américains passent de prêts classiques à des prêts à taux d’appel, puis à des prêts sans vérification de revenus, pariant sur la hausse continue des prix.",
    auteurs: ["minsky", "keynes", "galbraith"], questions: ["crises"], voir: ["cycles", "preteur-dernier-ressort", "alea-moral"], crise: "subprimes" },

  { id: "preteur-dernier-ressort", nom: "Prêteur en dernier ressort", cat: "monnaie",
    court: "Rôle de la banque centrale qui prête aux banques solvables mais à court de liquidités pour éviter les paniques.",
    texte: "Henry Thornton en 1802, puis Walter Bagehot dans Lombard Street (1873), en formulent la doctrine. En cas de panique, la banque centrale doit prêter librement, à un taux pénalisant, contre de bonnes garanties, aux banques solvables. Une banque peut être solide et manquer soudain de liquidités si ses déposants se ruent aux guichets ; sans prêteur en dernier ressort, la panique peut contaminer tout le système. Friedman et Schwartz reprochent à la Réserve fédérale de ne pas avoir joué ce rôle entre 1930 et 1933. Les banques centrales l’ont assumé massivement en 2008 et 2020. La difficulté est de distinguer une banque illiquide d’une banque insolvable, et de ne pas encourager l’imprudence.",
    exemple: "En mars 2023, la Banque nationale suisse met à disposition de Credit Suisse des dizaines de milliards de francs de liquidités avant son rachat par UBS.",
    auteurs: ["friedman", "minsky"], questions: ["crises", "monnaie"], voir: ["alea-moral", "instabilite-financiere"] },

  { id: "alea-moral", nom: "Aléa moral", cat: "monnaie",
    court: "Tendance à prendre davantage de risques quand on est protégé contre leurs conséquences.",
    texte: "Le terme vient de l’assurance : un assuré contre le vol surveille moins ses biens. Kenneth Arrow l’intègre à l’économie dans les années 1960. En finance, il désigne le risque que des banques, sachant qu’elles seront secourues en cas de difficulté parce qu’elles sont « trop grandes pour faire faillite », prennent des risques excessifs dont les gains leur reviennent et les pertes à la collectivité. Le débat est au cœur de la gestion des crises : sauver une banque évite une panique mais encourage les comportements futurs. Les réformes d’après 2008 (exigences de fonds propres accrues, mécanismes de résolution) cherchent à réduire ce dilemme.",
    exemple: "En laissant Lehman Brothers faire faillite en septembre 2008, les autorités américaines voulaient éviter l’aléa moral ; la panique qui suivit conduisit la Réserve fédérale à sauver l’assureur AIG dès le lendemain.",
    auteurs: ["stiglitz", "minsky", "friedman"], questions: ["crises"], voir: ["preteur-dernier-ressort", "asymetrie-information"] },

  { id: "equivalence-ricardienne", nom: "Équivalence ricardienne", cat: "monnaie",
    court: "Hypothèse selon laquelle financer une dépense publique par l’emprunt ou par l’impôt a les mêmes effets.",
    texte: "Ricardo l’envisage au sujet du financement des guerres napoléoniennes, avant d’en douter. Robert Barro la formalise en 1974. Si l’État baisse les impôts aujourd’hui en empruntant, des ménages prévoyants comprennent qu’il devra relever les impôts demain pour rembourser. Ils épargnent donc la baisse d’impôt, et la consommation ne bouge pas : la relance par le déficit serait inefficace. L’hypothèse repose sur des conditions fortes : horizon infini des ménages ou altruisme envers leurs descendants, accès parfait au crédit, information complète. Les études empiriques trouvent en général une équivalence partielle. Elle a nourri le scepticisme envers les relances budgétaires.",
    exemple: "Lors des chèques de relance américains de 2008, une partie importante a été épargnée ou consacrée au remboursement de dettes, mais pas la totalité.",
    auteurs: ["ricardo", "lucas"], questions: ["etat"], voir: ["multiplicateur", "anticipations-rationnelles"] },

  /* ---------- Commerce et développement ---------- */
  { id: "avantage-comparatif", nom: "Avantage comparatif", cat: "echange",
    court: "Un pays gagne à se spécialiser dans les productions où son coût d’opportunité est le plus faible.",
    texte: "Ricardo l’expose en 1817 avec l’Angleterre et le Portugal. Le Portugal produit drap et vin avec moins de travail, mais son avantage est relativement plus grand pour le vin. En se spécialisant, le Portugal dans le vin, l’Angleterre dans le drap, et en échangeant, les deux pays obtiennent davantage des deux biens. Samuelson disait que c’était la seule proposition des sciences sociales à la fois vraie et non évidente. La théorie suppose le plein emploi, la mobilité des facteurs entre secteurs et l’immobilité entre pays. Elle ne dit pas que tout le monde gagne : les travailleurs des secteurs concurrencés peuvent perdre, ce que Stolper et Samuelson ont formalisé.",
    exemple: "La Suisse importe la majeure partie de son textile et exporte des produits pharmaceutiques et des machines de précision.",
    auteurs: ["ricardo", "samuelson", "mill"], questions: ["commerce"], voir: ["taux-de-change", "cout-opportunite", "rendements-croissants"], lab: 2 },

  { id: "taux-de-change", nom: "Taux de change", cat: "echange",
    court: "Le prix d’une monnaie exprimé dans une autre, qui se forme sur le marché des changes.",
    texte: "Le taux de change dit combien de francs il faut pour obtenir un euro ou un dollar. Depuis la fin du système de Bretton Woods, au début des années 1970, la plupart des grandes monnaies flottent : leur valeur dépend de l’offre et de la demande. Quand une monnaie s’apprécie, les importations deviennent moins chères et les exportations plus chères pour les étrangers. À long terme, les taux de change tendent à refléter les écarts d’inflation (parité des pouvoirs d’achat, Cassel) ; à court terme, ils dépendent des taux d’intérêt, des anticipations et de la confiance. Un pays ne peut avoir à la fois un change fixe, des capitaux libres et une politique monétaire autonome : c’est le triangle d’incompatibilité de Mundell et Fleming.",
    exemple: "Le 15 janvier 2015, la BNS abandonne le cours plancher de 1,20 franc pour un euro : en un jour, les produits suisses deviennent plus de 10 % plus chers pour les clients européens.",
    auteurs: ["ricardo", "keynes", "friedman", "krugman"], questions: ["commerce", "monnaie"], voir: ["avantage-comparatif", "politique-monetaire", "theorie-quantitative", "fonctions-monnaie"] },

  { id: "rendements-croissants", nom: "Rendements croissants", cat: "echange",
    court: "Situation où le coût unitaire baisse quand la quantité produite augmente.",
    texte: "Smith y voyait le fruit de la division du travail, Marshall distinguait économies internes (la taille de l’entreprise) et externes (la concentration d’une industrie dans une région). Les rendements croissants posent un problème à la théorie de la concurrence parfaite, car ils favorisent la concentration et le monopole. Krugman les intègre à partir de 1979 à la théorie du commerce et de la géographie : ils expliquent pourquoi des pays semblables commercent intensément, et pourquoi l’activité se concentre dans quelques métropoles. Ils sont aussi au cœur des économies de plateforme, où chaque utilisateur supplémentaire rend le service plus utile pour les autres (effets de réseau), favorisant la domination d’un seul acteur.",
    exemple: "L’horlogerie suisse s’est concentrée dans l’Arc jurassien, où fournisseurs spécialisés, savoir-faire et écoles se renforcent mutuellement.",
    auteurs: ["krugman", "marshall", "smith"], questions: ["commerce"], voir: ["avantage-comparatif", "concurrence-imparfaite"] },

  { id: "rente", nom: "Rente différentielle", cat: "echange",
    court: "Revenu tiré d’une ressource rare et de qualité supérieure, sans effort supplémentaire de son propriétaire.",
    texte: "Formulée en 1815 simultanément par Malthus, West et Ricardo, la rente différentielle naît de l’inégale fertilité des terres. Le prix du blé est fixé par le coût de production sur la terre la moins fertile cultivée ; les meilleures terres dégagent un surplus qui revient au propriétaire. Le concept s’est étendu : rente minière, rente urbaine (un emplacement au centre-ville), rente de monopole, rente des talents exceptionnels. Mill et Henry George proposent de taxer la rente foncière, qui ne récompense aucun effort. Les économistes parlent aujourd’hui de « recherche de rente » pour désigner les efforts déployés pour obtenir un privilège plutôt que pour produire.",
    exemple: "Le prix d’un appartement à Genève ou Zurich reflète moins le coût de construction que la rareté des terrains bien situés.",
    auteurs: ["ricardo", "malthus", "mill"], questions: ["commerce", "inegalites"], voir: ["valeur-travail", "r-g"] },

  { id: "institutions-inclusives", nom: "Institutions inclusives et extractives", cat: "echange",
    court: "Chez Acemoglu et Robinson, les institutions qui ouvrent l’activité à tous s’opposent à celles qui servent une élite.",
    texte: "Les institutions économiques inclusives protègent la propriété du plus grand nombre, garantissent des contrats exécutoires, permettent l’entrée de nouveaux concurrents et l’accès à l’éducation. Les institutions extractives concentrent pouvoir et ressources entre les mains d’une élite qui prélève la richesse produite par d’autres. Elles vont de pair avec des institutions politiques du même type. Les élites extractives craignent la destruction créatrice, qui menace leurs positions, et la bloquent. Acemoglu et Robinson illustrent la thèse par Nogales, ville coupée en deux par la frontière américano-mexicaine, ou par les deux Corées. Les critiques soulignent le flou de la définition et l’exemple de la Chine, qui a connu une croissance rapide avec des institutions politiques non inclusives.",
    exemple: "La Corée du Nord et la Corée du Sud partagent l’histoire, la langue et la géographie ; le revenu par habitant du Sud est estimé à plus de vingt fois celui du Nord.",
    auteurs: ["acemoglu", "khaldoun"], questions: ["inegalites", "etat"], voir: ["destruction-creatrice"] },

  /* ---------- Répartition et bien-être ---------- */
  { id: "plus-value", nom: "Plus-value", cat: "repartition",
    court: "Chez Marx, la différence entre la valeur créée par le travail et la valeur de la force de travail payée par le salaire.",
    texte: "Marx part du constat que, sur le marché, les marchandises s’échangent à leur valeur. Le profit ne peut donc venir de la circulation, mais de la production. L’ouvrier vend sa force de travail, payée à sa valeur de reproduction, et travaille plus longtemps qu’il ne faut pour produire l’équivalent de son salaire. Le surtravail produit la plus-value, que le capitaliste s’approprie. Marx distingue la plus-value absolue, obtenue en allongeant la journée, et la plus-value relative, obtenue en réduisant par la productivité le temps nécessaire à produire les biens de l’ouvrier. Le taux de plus-value (plus-value rapportée aux salaires) mesure le degré d’exploitation. Le concept dépend de la théorie de la valeur-travail, abandonnée par l’économie dominante.",
    exemple: "Dans l’exemple de Marx, un fileur produit en six heures l’équivalent de son salaire et travaille douze heures : le taux de plus-value est de 100 %.",
    auteurs: ["marx", "ricardo"], questions: ["valeur", "inegalites"], voir: ["valeur-travail", "r-g"] },

  { id: "optimum-pareto", nom: "Optimum de Pareto", cat: "repartition",
    court: "Situation où l’on ne peut améliorer le sort de personne sans détériorer celui d’au moins une autre personne.",
    texte: "Pareto propose ce critère en 1906 pour juger les situations économiques sans comparer le bonheur des individus. Il est au cœur de l’économie du bien-être : le premier théorème établit qu’un équilibre de concurrence parfaite est Pareto-optimal ; le second, que tout optimum peut être atteint par le marché après une redistribution forfaitaire des dotations. Le critère est minimal : il ne dit rien de la justice de la répartition, une situation très inégale pouvant être optimale. Il est souvent indécidable, la plupart des politiques faisant des gagnants et des perdants. Les économistes utilisent alors le critère de Kaldor-Hicks : une mesure est souhaitable si les gagnants pourraient indemniser les perdants, même si l’indemnisation n’a pas lieu.",
    exemple: "Partager un gâteau entre deux personnes est Pareto-optimal quelle que soit la part de chacune, tant qu’aucune miette n’est perdue.",
    auteurs: ["pareto", "samuelson", "sen"], questions: ["inegalites", "etat"], voir: ["equilibre-general", "surplus", "capabilites"] },

  { id: "capabilites", nom: "Capabilités", cat: "repartition",
    court: "Chez Sen, l’ensemble des modes de vie qu’une personne est réellement en mesure de choisir.",
    texte: "Sen critique deux manières courantes de mesurer le bien-être. Le revenu ne dit pas ce qu’on peut en faire : une personne handicapée a besoin de plus de ressources pour se déplacer, une personne vivant dans un pays sans école publique ne peut acheter l’éducation de ses enfants. L’utilité, elle, s’adapte aux privations : les plus démunis apprennent à se contenter de peu. Sen propose d’évaluer les « fonctionnements » (être nourri, en bonne santé, instruit, participer à la vie publique) et surtout les capabilités, c’est-à-dire la liberté réelle de les atteindre. L’approche a inspiré l’Indice de développement humain (1990), qui combine revenu, santé et éducation.",
    exemple: "Le Kerala, État indien au revenu modeste, a longtemps eu une espérance de vie et un taux d’alphabétisation proches de ceux de pays bien plus riches.",
    auteurs: ["sen", "aristote"], questions: ["inegalites"], voir: ["pib", "optimum-pareto"] },

  { id: "r-g", nom: "r > g", cat: "repartition",
    court: "Chez Piketty, la situation où le rendement du capital dépasse la croissance, favorisant la concentration des patrimoines.",
    texte: "Si les patrimoines rapportent 5 % par an et que l’économie croît de 1,5 %, il suffit d’épargner une partie des revenus du capital pour que les fortunes croissent plus vite que les salaires. Piketty y voit la « contradiction centrale du capitalisme ». Le XXe siècle a fait exception : guerres, inflation et impôts progressifs ont réduit le rendement net du capital, tandis que la reconstruction accélérait la croissance. Il propose un impôt progressif mondial sur le capital. Les critiques soulignent que le rendement doit être mesuré net d’impôts et de dépréciation, que les grandes fortunes se renouvellent, et que l’écart r − g n’explique pas à lui seul l’évolution des inégalités observée selon les pays.",
    exemple: "Selon Piketty, vers 1910, les 10 % les plus riches détiennent environ 90 % du patrimoine en France et au Royaume-Uni.",
    auteurs: ["piketty", "acemoglu", "marx"], questions: ["inegalites"], voir: ["courbe-kuznets", "rente"] },

  { id: "courbe-kuznets", nom: "Courbe de Kuznets", cat: "repartition",
    court: "Hypothèse d’une relation en U inversé entre développement et inégalités.",
    texte: "En 1955, Simon Kuznets observe, avec prudence et sur peu de données, que les inégalités de revenus ont augmenté pendant l’industrialisation, puis diminué dans les pays riches au XXe siècle. Il suggère une explication : le passage de l’agriculture à l’industrie crée d’abord un écart entre secteurs, puis l’urbanisation, l’éducation et l’organisation politique des travailleurs réduisent les inégalités. La courbe a été interprétée comme une loi rassurante, selon laquelle la croissance résoudrait d’elle-même le problème. La remontée des inégalités depuis 1980 dans les pays riches l’a démentie. Pour Piketty, la baisse du XXe siècle tient aux chocs politiques et militaires plutôt qu’à une dynamique spontanée du développement.",
    exemple: "Aux États-Unis, la part du revenu national reçue par les 10 % les plus aisés passe d’environ 45 % en 1928 à environ 33 % en 1950, puis remonte au-dessus de 45 % dans les années 2010.",
    auteurs: ["piketty", "pareto"], questions: ["inegalites"], voir: ["r-g"] },

  { id: "externalite", nom: "Externalité", cat: "repartition",
    court: "Effet d’une activité sur des tiers, positif ou négatif, qui n’est pas pris en compte par les prix.",
    texte: "Marshall en a l’intuition avec les économies externes ; Arthur Pigou en fait en 1920 une théorie des défaillances du marché. Une usine qui pollue une rivière impose un coût aux pêcheurs sans le payer : elle produit trop. Un apiculteur dont les abeilles pollinisent les vergers voisins rend un service non rémunéré : il produit trop peu. Pigou propose de corriger ces écarts par des taxes et des subventions. Ronald Coase objecte en 1960 que les parties peuvent négocier directement si les droits de propriété sont clairs et les coûts de transaction faibles. Le changement climatique est souvent décrit comme la plus grande externalité de l’histoire, et la taxe carbone comme une taxe pigouvienne.",
    exemple: "La Suisse prélève depuis 2008 une taxe sur le CO₂ des combustibles, dont une large part est redistribuée à la population.",
    auteurs: ["marshall", "samuelson", "ostrom"], questions: ["etat"], voir: ["bien-public", "biens-communs"] },

  { id: "bien-public", nom: "Bien public", cat: "repartition",
    court: "Bien non rival et non excluable, que le marché ne peut fournir correctement.",
    texte: "Samuelson en donne en 1954 une définition rigoureuse. Un bien est non rival si son usage par l’un ne diminue pas celui des autres, non excluable si l’on ne peut empêcher personne d’en profiter. La défense nationale, l’éclairage public, la recherche fondamentale ou un phare en sont des exemples. Chacun a intérêt à laisser les autres payer : c’est le problème du passager clandestin. Le marché en fournit donc trop peu, ce qui justifie leur financement par l’impôt. Les économistes distinguent aussi les biens de club, excluables mais non rivaux (une autoroute à péage peu fréquentée), et les biens communs, rivaux mais non excluables (une pêcherie).",
    exemple: "Ronald Coase a montré en 1974 que des phares anglais avaient longtemps été financés par des péages portuaires privés, nuançant l’exemple classique.",
    auteurs: ["samuelson", "smith"], questions: ["etat"], voir: ["externalite", "biens-communs"] },

  { id: "biens-communs", nom: "Biens communs", cat: "repartition",
    court: "Ressources rivales mais difficilement excluables, exposées à la surexploitation en l’absence de règles.",
    texte: "Une pêcherie, une nappe phréatique, un pâturage : chaque usager réduit ce qui reste pour les autres, mais il est difficile d’en interdire l’accès. Garrett Hardin conclut en 1968 à une « tragédie » inévitable, sauf à privatiser ou à étatiser. Elinor Ostrom montre en 1990 que des communautés d’usagers ont souvent su s’organiser durablement, et dégage huit principes communs à leurs réussites. Le concept s’est étendu aux communs de la connaissance, comme Wikipédia ou les logiciels libres, et aux communs mondiaux, comme l’atmosphère et les océans, pour lesquels l’auto-organisation est plus difficile.",
    exemple: "Les bisses du Valais, canaux d’irrigation séculaires, sont gérés par des consortages d’usagers qui fixent les tours d’eau et les corvées d’entretien.",
    auteurs: ["ostrom", "aristote"], questions: ["etat"], voir: ["externalite", "bien-public"], lab: 4 },

  /* ---------- Institutions et comportements ---------- */
  { id: "aversion-pertes", nom: "Aversion aux pertes", cat: "institutions",
    court: "Tendance à ressentir une perte environ deux fois plus fortement qu’un gain de même montant.",
    texte: "Kahneman et Tversky l’établissent dans la théorie des perspectives (1979). Nous évaluons les résultats par rapport à un point de référence, souvent la situation actuelle, et non en richesse totale. Une perte de 100 francs fait plus mal qu’un gain de 100 francs ne réjouit. Cette asymétrie explique l’effet de dotation, qui nous fait exiger davantage pour céder un objet que nous ne paierions pour l’acquérir, le biais de statu quo, la réticence des investisseurs à vendre des titres en perte, ou la rigidité à la baisse des salaires nominaux. Elle a inspiré la conception de dispositifs d’épargne retraite par défaut et de nombreuses politiques fondées sur les « nudges ».",
    exemple: "Dans une expérience célèbre, des étudiants à qui l’on a donné une tasse demandent en moyenne, pour la revendre, plus du double de ce que ceux qui n’en ont pas sont prêts à payer.",
    auteurs: ["kahneman"], questions: ["valeur"], voir: ["anticipations-rationnelles"] },

  { id: "asymetrie-information", nom: "Asymétrie d’information", cat: "institutions",
    court: "Situation où une partie à l’échange en sait davantage que l’autre sur la qualité de ce qui est échangé.",
    texte: "George Akerlof publie en 1970 « The Market for Lemons » sur le marché des voitures d’occasion. Le vendeur connaît l’état de sa voiture, l’acheteur non. Celui-ci paie donc un prix moyen, qui décourage les propriétaires de bonnes voitures de vendre ; il ne reste que les « citrons », et le marché peut disparaître : c’est la sélection adverse. Michael Spence montre que les diplômes peuvent servir de signal de compétence ; Joseph Stiglitz analyse le rationnement du crédit et de l’assurance. Tous trois reçoivent le Nobel en 2001. L’asymétrie d’information explique les garanties, les marques, les réputations, la réglementation financière et sanitaire.",
    exemple: "Les plateformes de location entre particuliers reposent sur les notes et commentaires, qui réduisent l’asymétrie entre hôte et voyageur.",
    auteurs: ["stiglitz", "hayek"], questions: ["etat"], voir: ["alea-moral"] },

  { id: "consommation-ostentatoire", nom: "Consommation ostentatoire", cat: "institutions",
    court: "Chez Veblen, la dépense destinée à afficher son rang social plutôt qu’à satisfaire un besoin.",
    texte: "Veblen observe en 1899 que la classe aisée américaine dépense pour montrer qu’elle peut dépenser. Le prix élevé fait alors partie de l’attrait du bien : on parle de biens Veblen, dont la demande peut augmenter avec le prix. Chacun imitant le groupe immédiatement supérieur, la course au statut se propage dans toute la société. Les économistes Fred Hirsch et Robert Frank ont développé la notion de biens positionnels, dont la valeur dépend du rang relatif : si tout le monde achète une plus grosse voiture, personne ne gagne en prestige, mais tous ont dépensé davantage. Cette course peut justifier, selon Frank, une fiscalité progressive sur la consommation.",
    exemple: "Certaines maisons de luxe détruisaient leurs invendus plutôt que de les solder, pour préserver la rareté et le prix de leurs produits ; la France l’a interdit en 2022.",
    auteurs: ["veblen", "galbraith"], questions: ["valeur"], voir: ["offre-demande"] },

  { id: "encastrement", nom: "Encastrement", cat: "institutions",
    court: "Idée selon laquelle l’économie est prise dans les relations sociales, politiques et culturelles, et ne fonctionne jamais comme une sphère séparée.",
    texte: "Karl Polanyi observe en 1944 que, pendant la plus grande partie de l’histoire, la production et l’échange étaient réglés par la parenté, la religion, la coutume ou l’autorité politique : l’économie était « encastrée » dans la société. Le XIXe siècle tente l’inverse, faire de la société une annexe d’un marché autorégulateur, où le travail, la terre et la monnaie s’achètent et se vendent comme des marchandises. Pour Polanyi, cette tentative provoque une réaction de protection, lois sociales, syndicats, protectionnisme, qu’il appelle le « double mouvement ». Les sociologues de l’économie ont repris la notion, en montrant que même les marchés modernes reposent sur la confiance, les réseaux et les règles.",
    exemple: "Les paiements directs à l’agriculture suisse, l’article constitutionnel sur la sécurité alimentaire ou les règles sur l’aménagement du territoire montrent que la terre et l’alimentation ne sont pas laissées au seul marché.",
    auteurs: ["polanyi", "veblen", "ostrom"], questions: ["etat", "crises"], voir: ["institutions-inclusives", "biens-communs"] },
  { id: "monnaie-endogene", nom: "Monnaie endogène", cat: "monnaie",
    court: "Thèse selon laquelle la monnaie est créée par les banques quand elles accordent des crédits, en fonction de la demande, et non fixée de l’extérieur par la banque centrale.",
    texte: "Dans la vision des manuels, la banque centrale fixe la quantité de monnaie, et les banques prêtent l’épargne qu’on leur a confiée. Les post-keynésiens, de Nicholas Kaldor à Basil Moore, soutiennent l’inverse : quand une banque accorde un crédit, elle crée en même temps un dépôt sur le compte de l’emprunteur. « Les crédits font les dépôts. » La quantité de monnaie dépend donc de la demande de crédit des entreprises et des ménages ; la banque centrale agit surtout par le taux d’intérêt. En 2014, la Banque d’Angleterre a confirmé cette description dans un article de son bulletin trimestriel. La théorie moderne de la monnaie, portée par Stephanie Kelton, prolonge l’idée à la dépense publique.",
    exemple: "Quand une banque suisse accorde un prêt hypothécaire de 800 000 francs, elle inscrit cette somme sur le compte de l’acheteur : de la monnaie nouvelle apparaît, et disparaît à mesure que le prêt est remboursé.",
    auteurs: ["kelton", "minsky", "keynes"], questions: ["monnaie", "finance"], voir: ["politique-monetaire", "fonctions-monnaie", "theorie-quantitative"] },
  { id: "travail-non-remunere", nom: "Travail non rémunéré", cat: "repartition",
    court: "Travail domestique, soins aux proches et bénévolat, qui produisent des biens et des services sans être payés, et que le PIB ne compte pas.",
    texte: "Cuisiner, faire le ménage, élever des enfants, soigner un parent âgé : ces activités produisent des services utiles, mais comme elles ne passent pas par un marché, la comptabilité nationale les ignore. Marilyn Waring montre en 1988 que cette convention rend invisible une grande partie du travail des femmes, et donc absente des politiques publiques. Depuis, de nombreux offices statistiques mesurent ce travail par des enquêtes sur l’emploi du temps et l’estiment en argent dans des « comptes satellites ». La question touche les retraites, l’égalité salariale, l’accueil des enfants et le vieillissement de la population.",
    exemple: "Selon l’OFS, on consacre en Suisse davantage d’heures au travail non rémunéré qu’au travail rémunéré ; sa valeur est estimée à plusieurs centaines de milliards de francs par an. Les femmes en assurent la plus grande part.",
    auteurs: ["waring", "sen"], questions: ["inegalites", "croissance"], voir: ["pib", "capabilites"] },
  { id: "mode-regulation", nom: "Mode de régulation", cat: "macro",
    court: "Ensemble d’institutions, salaires, concurrence, monnaie, État, qui assure pendant une période la stabilité de la croissance capitaliste.",
    texte: "Pour l’école française de la régulation, fondée par Michel Aglietta en 1976 avec Robert Boyer, le capitalisme n’a pas de tendance naturelle à l’équilibre. Il connaît pourtant de longues périodes de croissance stable, parce qu’un ensemble cohérent d’institutions encadre les comportements. Après 1945, le « fordisme » associe production de masse, conventions collectives qui partagent les gains de productivité, consommation de masse et État social. Quand ces institutions ne s’accordent plus, une « grande crise » éclate, comme dans les années 1970, et un nouveau mode de régulation se met en place, dominé depuis par la finance et la mondialisation.",
    exemple: "La « paix du travail » de 1937 dans l’industrie suisse des machines et des métaux, où syndicats et patrons renoncent à la grève et au lock-out en échange de la négociation, est une pièce du mode de régulation suisse.",
    auteurs: ["aglietta", "marx", "keynes"], questions: ["crises", "croissance"], voir: ["cycles", "stagflation"] },
  { id: "choix-public", nom: "Théorie des choix publics", cat: "institutions",
    court: "Application aux hommes politiques et aux fonctionnaires de l’hypothèse d’intérêt personnel.",
    texte: "James Buchanan et Gordon Tullock publient en 1962 The Calculus of Consent. Ils reprochent à l’économie publique de supposer un État bienveillant qui corrige les défaillances du marché. Les élus cherchent à être réélus, les administrations à accroître leur budget, les groupes d’intérêt à obtenir des privilèges. Les défaillances de l’État peuvent donc être aussi graves que celles du marché. Les petits groupes très motivés, comme les producteurs d’un secteur protégé, l’emportent souvent sur les grands groupes diffus, comme les consommateurs, ce que Mancur Olson avait analysé en 1965. Buchanan reçoit le Nobel en 1986. Ses critiques jugent la théorie trop cynique, aveugle au rôle des idées et des valeurs dans la vie publique.",
    exemple: "Les subventions agricoles profitent à quelques centaines de milliers d’exploitants très organisés, et coûtent un peu à des centaines de millions de consommateurs qui ne s’en aperçoivent guère.",
    auteurs: ["friedman", "hayek", "mises"], questions: ["etat"], voir: ["bien-public"] }
];
